-- Additive initial schema. Apply to a fresh STAMPED Supabase project, never reset a live database.
create table public.cities (id text primary key, name text not null, country text not null, created_at timestamptz not null default now());
create table public.interests (id text primary key, name text not null);
create table public.experiences (id text primary key, city_id text not null references public.cities(id), title text not null, published boolean not null default false, is_seed boolean not null default false, content jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,city_id));
create table public.experience_interests (experience_id text references public.experiences(id) on delete cascade, interest_id text references public.interests(id), primary key(experience_id,interest_id));
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, home_city_id text references public.cities(id), onboarding_complete boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_interests (user_id uuid references public.profiles(id) on delete cascade, interest_id text references public.interests(id), primary key(user_id,interest_id));
create table public.travel_intents (user_id uuid references public.profiles(id) on delete cascade, city_id text references public.cities(id), status text not null check(status in ('Definitely going','Probably going','Thinking about it')), created_at timestamptz not null default now(), primary key(user_id,city_id));
create table public.plans (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, day_count int not null default 3 check(day_count between 1 and 30), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,user_id));
create table public.plan_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, plan_id uuid not null, experience_id text not null references public.experiences(id), day int check(day between 1 and 30), position int not null default 0, added_at timestamptz not null default now(), foreign key(plan_id,user_id) references public.plans(id,user_id) on delete cascade, unique(user_id,experience_id));
create table public.itineraries (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, city_id text not null references public.cities(id), title text not null default '', starts_on date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,user_id));
create table public.itinerary_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, itinerary_id uuid not null, experience_id text not null references public.experiences(id), day int not null check(day>0), position int not null default 0, foreign key(itinerary_id,user_id) references public.itineraries(id,user_id) on delete cascade, unique(itinerary_id,experience_id));
create table public.stamps (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, experience_id text not null, city_id text not null references public.cities(id), completed_at timestamptz not null default now(), rating int check(rating between 1 and 5), amount_spent numeric(12,2) check(amount_spent between 0 and 1000000), currency text not null default 'GBP' check(currency='GBP'), duration_minutes int check(duration_minutes between 1 and 10080), tip text not null default '' check(char_length(tip)<=500), evidence_status text not null default 'standard' check(evidence_status in ('standard','photo')), cover_photo text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(experience_id,city_id) references public.experiences(id,city_id), unique(user_id,experience_id), unique(id,user_id));
create table public.stamp_media (id text primary key, stamp_id uuid not null, user_id uuid not null references public.profiles(id) on delete cascade, storage_path text not null unique, alt text not null default '' check(char_length(alt)<=200), slot int not null check(slot between 1 and 5), created_at timestamptz not null default now(), foreign key(stamp_id,user_id) references public.stamps(id,user_id) on delete cascade, unique(stamp_id,slot));
create index plan_items_order on public.plan_items(user_id,day,position);
create index stamps_city on public.stamps(user_id,city_id,completed_at desc);
create index stamp_media_owner on public.stamp_media(user_id,stamp_id);
create index itineraries_owner on public.itineraries(user_id);
create index itinerary_items_owner on public.itinerary_items(user_id);
create index experiences_city on public.experiences(city_id) where published;
create function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end $$;
do $$ declare t text;begin foreach t in array array['profiles','plans','stamps','experiences','itineraries'] loop execute format('create trigger touch_updated_at before update on public.%I for each row execute function public.touch_updated_at()',t);end loop;end $$;
